  }

  // ------------------------------------------------------------------ state

  var state = {
    token: store.get(TOKEN_KEY),
    user: null,
    roots: [],
    rootId: null,
    path: "/",
    entries: [],
    next: null,
    loading: false,
    error: null,
    selected: new Set(),
  };
  var loadCounter = 0;
  var shell = null;
  var collator = new Intl.Collator(undefined, { numeric: true, sensitivity: "base" });

  function currentRoot() {
    for (var i = 0; i < state.roots.length; i++) {
      if (state.roots[i].id === state.rootId) return state.roots[i];
    }
    return null;
  }

  function canWrite() {
    var root = currentRoot();
    return !!root && root.writable === true && root.available !== false;
  }

  // -------------------------------------------------------------------- API

  function ApiError(status, code, retryAfter) {
    this.name = "ApiError";
    this.status = status;
    this.code = code;
    this.retryAfter = retryAfter;
  }
  ApiError.prototype = Object.create(Error.prototype);

  function request(method, path, options) {
    var opts = options || {};
    var url = new URL(path, window.location.origin);
    var query = opts.query || {};
    Object.keys(query).forEach(function (key) {
      if (query[key] !== undefined && query[key] !== null) url.searchParams.set(key, String(query[key]));
    });

    var init = { method: method, headers: {}, cache: "no-store", credentials: "omit", referrerPolicy: "no-referrer" };
    var authed = opts.auth !== false;
    if (authed && state.token) init.headers.Authorization = "Bearer " + state.token;
    if (opts.json !== undefined) {
      init.headers["Content-Type"] = "application/json";
      init.body = JSON.stringify(opts.json);
    }

    return fetch(url.toString(), init).then(
      function (response) {
        if (response.status === 401 && authed && state.token) {
          endSession("Your session ended. Sign in again to continue.");
          throw new ApiError(401, "unauthorized", null);
        }
        if (!response.ok) {
          return response.json().then(
            function (data) { return data; },
            function () { return null; }
          ).then(function (data) {
            var code = data && typeof data.error === "string" ? data.error : "error";
            throw new ApiError(response.status, code, response.headers.get("Retry-After"));
          });
        }
        if (response.status === 204) return null;
        return response.json();
      },
      function () {
        throw new ApiError(0, "network", null);
      }
    );
  }

  function rootUrl(action) {
    return "/api/v1/roots/" + encode(state.rootId) + "/" + action;
  }

  // ------------------------------------------------------------ session flow

  function endSession(message) {
    if (!state.token && !shell) return;
    var resume = window.location.hash;
    store.set(RESUME_KEY, resume && resume.length > 1 ? resume : null);
    state.token = null;
    state.user = null;
    store.set(TOKEN_KEY, null);
    shell = null;
    renderLogin(message || null);
  }

  function signOut() {
    request("POST", "/api/v1/auth/logout").then(
      function () {},
      function () {}
    ).then(function () {
      state.token = null;
      state.user = null;
      store.set(TOKEN_KEY, null);
      store.set(RESUME_KEY, null);
      shell = null;
      window.location.hash = "";
      renderLogin(null);
    });
  }

  // ------------------------------------------------------------------ login

  function renderLogin(message) {
    var insecure = window.location.protocol === "http:" &&
      ["localhost", "127.0.0.1", "[::1]"].indexOf(window.location.hostname) === -1;

    var errorBox = h("p", { class: "notice error hidden", role: "alert" });
    var infoBox = message ? h("p", { class: "notice", role: "status", text: message }) : null;
    var username = h("input", { id: "username", name: "username", type: "text", autocomplete: "username", autocapitalize: "none", spellcheck: "false", required: true });
    var password = h("input", { id: "password", name: "password", type: "password", autocomplete: "current-password", required: true });
    var submit = button("Sign in", null, { type: "submit", kind: "primary", keepText: true });

    function fail(text) {
      errorBox.textContent = text;
      errorBox.classList.remove("hidden");
    }

    var form = h(
      "form",
      {
        novalidate: true,
        onsubmit: function (event) {
          event.preventDefault();
          if (!username.value.trim() || !password.value) {
            fail("Enter your username and password.");
            return;
          }
          errorBox.classList.add("hidden");
          submit.disabled = true;
          request("POST", "/api/v1/auth/login", { json: { username: username.value, password: password.value }, auth: false }).then(
            function (data) {
              state.token = data.token;
              state.user = data.user;
              store.set(TOKEN_KEY, data.token);
              password.value = "";
              return enterApp();
            },
            function (error) {
              submit.disabled = false;
              password.value = "";
              password.focus();
              fail(describeError(error));
            }
          );
        },
      },
      infoBox,
      errorBox,
      h("div", { class: "field" }, h("label", { for: "username", text: "Username" }), username),
      h("div", { class: "field" }, h("label", { for: "password", text: "Password" }), password),
      submit
    );

    appEl.replaceChildren(
      h(
        "div",
        { class: "login-wrap" },
        h(
          "main",
          { class: "card" },
          h("div", { class: "brand" }, h("span", { class: "brand-mark", "aria-hidden": "true" }), h("h1", { text: "Atomic Carton" })),
          h("p", { class: "lede", text: "Sign in to reach the files on this phone." }),
          form,
          insecure
            ? h("p", { class: "insecure", text: "This connection isn't encrypted, so anyone on this network could read your password and files. Use the https:// address if you can." })
            : null
        )
      )
    );
    username.focus();
  }

  // -------------------------------------------------------------- app entry

  function enterApp() {
    return Promise.all([
      state.user ? Promise.resolve(state.user) : request("GET", "/api/v1/me"),
      request("GET", "/api/v1/roots"),
    ]).then(
      function (results) {
        state.user = results[0];
        state.roots = results[1].roots;
        buildShell();
        var resume = store.get(RESUME_KEY);
        if (resume) {
          store.set(RESUME_KEY, null);
          if (window.location.hash !== resume) window.location.hash = resume;
        }
        route();
      },
      function (error) {
        if (error && error.code === "unauthorized") return;
        state.token = null;
        store.set(TOKEN_KEY, null);
        renderLogin(describeError(error));
      }
    );
  }

  function buildHash(rootId, path) {
    return "#/" + encode(rootId) + (path === "/" ? "/" : "/" + pathSegments(path).map(encode).join("/"));
  }

  function parseHash() {
    var hash = window.location.hash;
    if (hash.indexOf("#/") !== 0) return null;
    var rest = hash.slice(2);
    var cut = rest.indexOf("/");
    var rawRoot = cut === -1 ? rest : rest.slice(0, cut);
    var rawPath = cut === -1 ? "" : rest.slice(cut + 1);
    try {
      var segments = rawPath.split("/").filter(Boolean).map(decodeURIComponent);
      return { rootId: decodeURIComponent(rawRoot), path: "/" + segments.join("/") };
    } catch (_) {
      return null;
    }
  }

  function goTo(rootId, path) {
    var wanted = buildHash(rootId, path);
    if (window.location.hash === wanted) route();
    else window.location.hash = wanted;
  }

  function route() {
    if (!state.token || !shell) return;
    var target = parseHash();
    var known = target && state.roots.some(function (root) { return root.id === target.rootId; });
    if (!known) {
      var preferred = state.roots.filter(function (root) { return root.isDefault; })[0] || state.roots[0];
      if (!preferred) {
        state.rootId = null;
        renderRoots();
        renderCrumbs();
        renderToolbar();
        renderFiles();
        return;
      }
      target = { rootId: preferred.id, path: "/" };
      window.history.replaceState(null, "", buildHash(target.rootId, target.path));
    }
    state.rootId = target.rootId;
    state.path = target.path;
    renderRoots();
    renderCrumbs();
    loadDirectory(true);
  }

  window.addEventListener("hashchange", route);

  // ------------------------------------------------------------------ shell

  function buildShell() {
    shell = {
      roots: h("nav", { class: "roots", "aria-label": "Storage locations" }),
      crumbs: h("nav", { class: "crumbs", "aria-label": "Folder path" }),
      toolbar: h("div", { class: "toolbar", role: "toolbar", "aria-label": "File actions" }),
      panel: h("section", { class: "panel", "aria-label": "Files" }),
      uploads: h("aside", { class: "uploads hidden", "aria-label": "Uploads" }),
      fileInput: h("input", {
        type: "file",
        multiple: true,
        class: "hidden",
        "aria-hidden": "true",
        tabindex: "-1",
        onchange: function (event) {
          var files = Array.prototype.slice.call(event.target.files);
          event.target.value = "";
          queueUploads(files);
        },
      }),
    };

    var panel = shell.panel;
    panel.addEventListener("dragover", function (event) {
      if (!canWrite() || !hasFiles(event)) return;
      event.preventDefault();
      panel.classList.add("dragging");
    });
    panel.addEventListener("dragleave", function () { panel.classList.remove("dragging"); });
    panel.addEventListener("drop", function (event) {
      panel.classList.remove("dragging");
      if (!canWrite() || !hasFiles(event)) return;
      event.preventDefault();
      collectDropped(event.dataTransfer);
    });

    appEl.replaceChildren(
      h(
        "header",
        { class: "topbar" },
        h("div", { class: "brand" }, h("span", { class: "brand-mark", "aria-hidden": "true" }), h("h1", { text: "Atomic Carton" })),
        h("span", { class: "spacer" }),
        h("span", { class: "who", text: state.user ? state.user.username : "" }),
        button("Sign out", "logout", { onclick: signOut, small: true, kind: "quiet" })
      ),
      h("main", { class: "page" }, shell.roots, shell.crumbs, shell.toolbar, shell.panel),
      shell.uploads,
      shell.fileInput
    );
    window.addEventListener("beforeunload", warnIfUploading);
  }

  function hasFiles(event) {
    var types = event.dataTransfer && event.dataTransfer.types;
    return !!types && Array.prototype.indexOf.call(types, "Files") !== -1;
  }

  function warnIfUploading(event) {
    if (uploads.items.some(function (item) { return item.status === "uploading" || item.status === "waiting"; })) {
      event.preventDefault();
      event.returnValue = "";
    }
  }

  function renderRoots() {
    if (state.roots.length < 2) {
      shell.roots.replaceChildren();
      return;
    }
    shell.roots.replaceChildren.apply(
      shell.roots,
      state.roots.map(function (root) {
        return h(
          "button",
          {
            type: "button",
            class: "chip",
            "aria-current": root.id === state.rootId ? "true" : "false",
            onclick: function () { goTo(root.id, "/"); },
          },
          icon("folder"),
          root.name,
          root.available === false ? h("small", { text: "offline" }) : null,
          root.writable === false ? h("small", { text: "read-only" }) : null
        );
      })
    );
  }

  function renderCrumbs() {
    var root = currentRoot();
    if (!root) {
      shell.crumbs.replaceChildren();
      return;
    }
    var parts = pathSegments(state.path);
    var nodes = [];
    nodes.push(crumb(root.name, "/", parts.length === 0));
    var walked = "";
    parts.forEach(function (part, index) {
      walked += "/" + part;
      nodes.push(h("span", { class: "sep", "aria-hidden": "true", text: "/" }));
      nodes.push(crumb(part, walked, index === parts.length - 1));
    });
    shell.crumbs.replaceChildren.apply(shell.crumbs, nodes);
  }

  function crumb(label, path, isCurrent) {
    return h("button", {
      type: "button",
      text: label,
      "aria-current": isCurrent ? "page" : null,
      onclick: function () { if (!isCurrent) goTo(state.rootId, path); },
    });
  }

  // --------------------------------------------------------------- toolbar

  function selectedEntries() {
    return state.entries.filter(function (entry) { return state.selected.has(entry.name); });
  }

  function renderToolbar() {
    var root = currentRoot();
    if (!root) {
      shell.toolbar.replaceChildren();
      return;
    }
    var chosen = selectedEntries();
    var writable = canWrite();
    var nodes = [];

    if (chosen.length === 0) {
      if (writable) {
        nodes.push(button("Upload", "upload", { kind: "primary", keepText: true, onclick: function () { shell.fileInput.click(); } }));
        nodes.push(button("New folder", "newfolder", { onclick: newFolder }));
      }
      nodes.push(button("Refresh", "refresh", { onclick: function () { loadDirectory(true); } }));
    } else {
      nodes.push(h("span", { class: "count", text: chosen.length + " selected" }));
      var single = chosen.length === 1 ? chosen[0] : null;
      if (single && single.type === "file") {
        var kind = kindOf(single.name);
        if (kind !== "file") nodes.push(button("Preview", "view", { onclick: function () { previewFile(single); } }));
        nodes.push(button("Download", "download", { onclick: function () { downloadFile(single); } }));
      }
      if (writable) {
        if (single) nodes.push(button("Rename", "edit", { onclick: function () { renameEntry(single); } }));
        nodes.push(button("Move", "move", { onclick: function () { moveOrCopy(chosen, true); } }));
        nodes.push(button("Copy", "copy", { onclick: function () { moveOrCopy(chosen, false); } }));
        nodes.push(button("Delete", "trash", { kind: "danger", onclick: function () { deleteEntries(chosen); } }));
      }
      nodes.push(button("Clear", "close", { kind: "quiet", onclick: function () { state.selected.clear(); renderFiles(); renderToolbar(); } }));
    }
    shell.toolbar.replaceChildren.apply(shell.toolbar, nodes);
  }

  // ------------------------------------------------------------- file list

  function sortEntries() {
    state.entries.sort(function (a, b) {
      if (a.type !== b.type) return a.type === "directory" ? -1 : 1;
      return collator.compare(a.name, b.name);
    });
  }

  function loadDirectory(reset) {
    var mine = ++loadCounter;
    if (reset) {
      state.entries = [];
      state.next = null;
      state.selected.clear();
    }
    state.loading = true;
    state.error = null;
    renderFiles();
    renderToolbar();

    var query = { path: state.path, limit: PAGE_SIZE };
    if (!reset && state.next) query.cursor = state.next;

    return request("GET", rootUrl("entries"), { query: query }).then(
      function (data) {
        if (mine !== loadCounter) return;
        state.entries = state.entries.concat(data.entries);
        sortEntries();
        state.next = data.nextCursor;
        state.loading = false;
        renderFiles();
        renderToolbar();
      },
      function (error) {
        if (mine !== loadCounter) return;
        state.loading = false;
        state.error = describeError(error);
        renderFiles();
        renderToolbar();
      }
    );
  }

  function renderFiles() {
    var panel = shell.panel;
    if (!state.rootId) {
      panel.replaceChildren(emptyState("No storage is shared yet", "Add a storage location in the Atomic Carton app on the phone."));
      return;
    }
    if (state.error) {
      panel.replaceChildren(
        h("div", { class: "empty" }, h("strong", { text: "Couldn't open this folder" }), h("p", { text: state.error }), button("Try again", "refresh", { onclick: function () { loadDirectory(true); } }))
      );
      return;
    }
    if (state.loading && state.entries.length === 0) {
      panel.replaceChildren(h("div", { class: "empty", role: "status", text: "Loading…" }));
      return;
    }
    if (state.entries.length === 0) {
      panel.replaceChildren(
        emptyState("This folder is empty", canWrite() ? "Drop files here or use Upload." : "Nothing here yet.")
      );
      return;
    }

    var allSelected = state.entries.length > 0 && state.entries.every(function (entry) { return state.selected.has(entry.name); });
    var headCheck = h("input", {
      type: "checkbox",
      checked: allSelected,
      "aria-label": "Select all",
      onchange: function (event) {
        if (event.target.checked) state.entries.forEach(function (entry) { state.selected.add(entry.name); });
        else state.selected.clear();
        renderFiles();
        renderToolbar();
      },
    });

    var body = h("tbody");
    state.entries.forEach(function (entry) {
      body.appendChild(renderRow(entry));
    });

    var nodes = [
      h(
        "table",
        { class: "files" },
        h("thead", null, h("tr", null, h("th", { class: "check" }, headCheck), h("th", { text: "Name" }), h("th", { class: "num", text: "Size" }), h("th", { class: "when", text: "Modified" }))),
        body
      ),
    ];
    if (state.next) {
      nodes.push(
        h("div", { class: "more" }, button(state.loading ? "Loading…" : "Load more", null, { keepText: true, disabled: state.loading, onclick: function () { loadDirectory(false); } }))
      );
    }
    panel.replaceChildren.apply(panel, nodes);
  }

  function emptyState(title, text) {
    return h("div", { class: "empty" }, h("strong", { text: title }), h("span", { text: text }));
  }

  function renderRow(entry) {
    var isDir = entry.type === "directory";
    var checked = state.selected.has(entry.name);
    var row = h("tr", { class: checked ? "selected" : null });

    var check = h("input", {
      type: "checkbox",
      checked: checked,
      "aria-label": "Select " + entry.name,
      onchange: function (event) {
        if (event.target.checked) state.selected.add(entry.name);
        else state.selected.delete(entry.name);
        row.classList.toggle("selected", event.target.checked);
        renderToolbar();
      },
    });

    var open = h(
      "button",
      {
        type: "button",
        class: "name-btn" + (isDir ? "" : " file"),
        onclick: function () {
          if (isDir) goTo(state.rootId, joinPath(state.path, entry.name));
          else openFile(entry);
        },
      },
      icon(iconFor(entry)),
      h("span", { class: "label", text: entry.name })
    );

    row.append(
      h("td", { class: "check" }, check),
      h("td", null, open),
      h("td", { class: "num", text: isDir ? "" : formatBytes(entry.size) }),
      h("td", { class: "when", text: formatWhen(entry.modified) })
    );
    return row;
  }

  function openFile(entry) {
    if (kindOf(entry.name) !== "file") previewFile(entry);
    else downloadFile(entry);
  }

  // ---------------------------------------------------------------- dialogs

  /**
   * A modal. [actions] are {label, value, kind, submit}. Resolves with the
   * chosen action's value, or null if dismissed. The one with `submit: true`
   * runs on Enter; its optional `check()` can veto closing.
   */
  function showDialog(title, content, actions, options) {
    var opts = options || {};
    return new Promise(function (resolve) {
      var dialog = h("dialog", { class: opts.wide ? "wide" : null, "aria-label": title });
      var done = false;

      function close(value) {
        if (done) return;
        done = true;
        if (dialog.open) dialog.close();
        dialog.remove();
        resolve(value);
      }

      var foot = h("div", { class: "d-foot" });
      actions.forEach(function (action) {
        foot.appendChild(
          h("button", {
            type: action.submit ? "submit" : "button",
            class: "btn" + (action.kind ? " " + action.kind : ""),
            text: action.label,
            onclick: action.submit ? null : function () { close(action.value); },
          })
        );
      });

      var submitAction = actions.filter(function (action) { return action.submit; })[0];
      var form = h(
        "form",
        {
          method: "dialog",
          onsubmit: function (event) {
            event.preventDefault();
            if (!submitAction) return;
            if (submitAction.check && submitAction.check() === false) return;
            close(submitAction.value);
          },
        },
        h("div", { class: "d-head" }, h("h2", { text: title }), h("button", { type: "button", class: "btn quiet small", "aria-label": "Close", onclick: function () { close(null); } }, icon("close"))),
        h("div", { class: "d-body" }, content),
        foot
      );
      dialog.appendChild(form);
      dialog.addEventListener("cancel", function (event) {
        event.preventDefault();
        close(null);
      });
      document.body.appendChild(dialog);
      dialog.showModal();
      var first = dialog.querySelector("input[type=text], input:not([type=hidden])");
      if (first && typeof first.select === "function") first.select();
    });
  }

  function promptText(options) {
    var input = h("input", { type: "text", id: "prompt-input", value: options.value || "", autocomplete: "off", autocapitalize: "none", spellcheck: "false" });
    var problem = h("p", { class: "notice error hidden", role: "alert" });
    var content = h("div", null, problem, h("div", { class: "field" }, h("label", { for: "prompt-input", text: options.label }), input));
    return showDialog(
      options.title,
      content,
      [
        { label: "Cancel", value: null },
        {
          label: options.confirmLabel,
          value: "ok",
          kind: "primary",
          submit: true,
          check: function () {
            var text = input.value.trim();
            if (!text) {
              problem.textContent = "Enter a name.";
              problem.classList.remove("hidden");
              return false;
            }
            if (text.indexOf("/") !== -1 || text.indexOf("\\") !== -1) {
              problem.textContent = "A name can't contain / or \\.";
              problem.classList.remove("hidden");
              return false;
            }
            return true;
          },
        },
      ]
    ).then(function (result) {
      return result === "ok" ? input.value.trim() : null;
    });
  }

  function confirmDialog(options) {
    return showDialog(
      options.title,
      h("p", { text: options.message }),
      [
        { label: "Cancel", value: false },
        { label: options.confirmLabel, value: true, kind: options.danger ? "danger" : "primary", submit: true },
      ]
    ).then(function (result) { return result === true; });
  }

  // ----------------------------------------------------------- file actions

  function withTicket(entry) {
    var path = joinPath(state.path, entry.name);
    return request("POST", rootUrl("ticket"), { json: { path: path } }).then(function (data) {
      if (!data || typeof data.url !== "string" || data.url.indexOf("/d/") !== 0) throw new ApiError(500, "error", null);
      return data.url;
    });
  }

  function downloadFile(entry) {
    withTicket(entry).then(
      function (url) {
        var link = h("a", { href: url, download: entry.name, rel: "noopener" });
        document.body.appendChild(link);
        link.click();
        link.remove();
      },
      function (error) { toast(describeError(error), true); }
    );
  }

  function previewFile(entry) {
    var kind = kindOf(entry.name);
    if (kind === "file") {
      downloadFile(entry);
      return;
    }
    if (kind === "text" && typeof entry.size === "number" && entry.size > MAX_TEXT_PREVIEW) {
      toast("That file is too large to preview. Downloading instead.");
      downloadFile(entry);
      return;
    }
    withTicket(entry).then(
      function (url) {
        var media;
        if (kind === "image") media = h("img", { src: url + "?inline=1", alt: entry.name });
        else if (kind === "video") media = h("video", { src: url + "?inline=1", controls: true, preload: "metadata" });
        else if (kind === "audio") media = h("audio", { src: url + "?inline=1", controls: true, preload: "metadata" });
        else {
          media = h("pre", { text: "Loading…" });
          fetch(url + "?inline=1", { credentials: "omit", cache: "no-store", referrerPolicy: "no-referrer" })
            .then(function (response) { return response.text(); })
            .then(function (text) { media.textContent = text; }, function () { media.textContent = "Couldn't load this file."; });
        }
        showDialog(
          entry.name,
          h("div", { class: "preview" }, media),
          [{ label: "Close", value: null }, { label: "Download", value: "download", kind: "primary", submit: true }],
          { wide: true }
        ).then(function (result) {
          if (media.pause) media.pause();
          if (result === "download") downloadFile(entry);
        });
      },
      function (error) { toast(describeError(error), true); }
    );
