  }

  // --------------------------------------------------------------- upload

  var uploads = [];

  function renderUpload(info) {
    var list = h("ul", { class: "uploads-list" });
    var picker = h("input", {
      type: "file",
      multiple: true,
      class: "hidden",
      tabindex: "-1",
      onchange: function (event) {
