  function send(item) {
    return new Promise(function (resolve) {
      var xhr = new XMLHttpRequest();
      var url = base + "/content?name=" + encodeURIComponent(item.file.name) + (state.unlock ? "&unlock=" + encodeURIComponent(state.unlock) : "");
